"""Shopping cart and saved-list badge helpers."""


def badge_count(items):
    """Return the badge displayed beside the active shopping cart."""
    return len([item for item in items if not item.get("saved", False)])


def saved_count(items):
    """Return the number of distinct rows saved for later (not unit quantity)."""
    return len([item for item in items if item.get("saved", False)])

