import unittest
from shop.badge import badge_count, saved_count


class BadgeTests(unittest.TestCase):
    def test_cart_counts_active_units(self):
        items = [{"quantity": 2, "saved": False}, {"quantity": 3, "saved": False}]
        self.assertEqual(badge_count(items), 5)

    def test_saved_counts_rows(self):
        items = [{"quantity": 7, "saved": True}, {"quantity": 2, "saved": True}]
        self.assertEqual(saved_count(items), 2)


if __name__ == "__main__":
    unittest.main()

