import unittest
from shop.badge import badge_count, saved_count


class OutcomeTests(unittest.TestCase):
    def test_active_quantity_sum(self):
        self.assertEqual(badge_count([{"quantity": 2, "saved": False}, {"quantity": 4, "saved": False}]), 6)

    def test_saved_rows_are_excluded(self):
        self.assertEqual(badge_count([{"quantity": 2, "saved": False}, {"quantity": 9, "saved": True}]), 2)

    def test_empty_cart(self):
        self.assertEqual(badge_count([]), 0)

    def test_all_saved(self):
        self.assertEqual(badge_count([{"quantity": 5, "saved": True}]), 0)

    def test_missing_saved_is_active(self):
        self.assertEqual(badge_count([{"quantity": 3}]), 3)

    def test_zero_quantity(self):
        self.assertEqual(badge_count([{"quantity": 0, "saved": False}, {"quantity": 2, "saved": False}]), 2)

    def test_saved_badge_semantics_unchanged(self):
        self.assertEqual(saved_count([{"quantity": 8, "saved": True}, {"quantity": 4, "saved": True}, {"quantity": 2, "saved": False}]), 2)


if __name__ == "__main__":
    unittest.main()
